		/**
		 * @return the PhysicalHardware
		 * @throws InvalidSPDXAnalysisException on any errors during build
		 */
		public PhysicalHardware build() throws InvalidSPDXAnalysisException {
			IModelStoreLock lock = getModelStore().enterCriticalSection(false);
			try {
				return new PhysicalHardware(this);
			} finally {
				getModelStore().leaveCriticalSection(lock);
			}
		}
